@extends('layouts.app') @section('title','Buat Pemesanan') @section('content')<div class="card" style="max-width:720px;margin:auto"><a href="{{ route('armada.index') }}">← Kembali ke armada</a><h1 style="margin-top:14px">Pesan {{ $armada->nama_kendaraan }}</h1><p class="price">Rp{{ number_format($armada->harga_sewa,0,',','.') }} <small>/ hari</small></p><form method="post" action="{{ route('booking.store',$armada) }}" id="booking">@csrf<div class="field"><label>Tanggal sewa</label><input type="date" name="tanggal_sewa" min="{{ now()->toDateString() }}" value="{{ old('tanggal_sewa',now()->toDateString()) }}" required></div><div class="field"><label>Durasi (hari)</label><input type="number" name="durasi" id="durasi" min="1" max="90" value="{{ old('durasi',1) }}" required></div><div class="field"><label>Layanan</label><select name="layanan" id="layanan"><option value="ambil">Ambil sendiri di lokasi</option><option value="diantar">Diantar ke alamat</option></select></div><div class="field" id="alamat"><label>Alamat pengantaran</label><textarea name="alamat_antar" rows="2">{{ old('alamat_antar') }}</textarea></div><div class="field"><label>Metode pembayaran</label><select name="metode_pembayaran" required><option>Transfer Bank</option><option>E-Wallet</option><option>QRIS</option></select></div><div class="card" style="background:#f5f7fb;margin:16px 0"><span class="muted">Estimasi total</span><div class="price" id="total">Rp{{ number_format($armada->harga_sewa,0,',','.') }}</div><small>Pembayaran pada versi ini masih berupa simulasi; tidak ada transaksi uang sungguhan.</small></div><button type="submit">Konfirmasi Pemesanan</button></form></div><script>const harga={{ (float)$armada->harga_sewa }};const dur=document.getElementById('durasi'),tot=document.getElementById('total'),lay=document.getElementById('layanan'),alamat=document.getElementById('alamat');function hitung(){tot.textContent=new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits